// GENERATED by tools/easy.js from tools/easy-src. Do not edit by hand.
const EASY = {"187e313":{"en":"Pick your Sylvaneth units that are inside the Creeping Overgrowth zone. For each one, roll a D3, then choose: heal that many damage OR bring back slain models (their total Health up to the roll).","el":"Διάλεξε τις μονάδες Sylvaneth σου που είναι μέσα στη Ζώνη Ανάπτυξης (Creeping Overgrowth). Για καθεμία ρίξε D3 και διάλεξε: γιάτρεψε τόσους πόντους ζημιάς όσο το ζάρι Ή φέρε πίσω σκοτωμένα μοντέλα (με συνολική Health μέχρι το ζάρι)."},"1u3qzmi":{"en":"The zone grows around terrain that has your green token. More tokens = bigger zone: 0-2 tokens 6\", 3-5 tokens 9\", 6-8 tokens 12\", 9+ tokens the whole table.","el":"Η Ζώνη Ανάπτυξης απλώνεται γύρω από στοιχεία εδάφους που έχουν δικό σου πράσινο δείκτη (overgrown token). Περισσότεροι δείκτες = μεγαλύτερη ζώνη: 0-2 δείκτες 6\", 3-5 δείκτες 9\", 6-8 δείκτες 12\", 9+ δείκτες όλο το τραπέζι."},"59cuq2":{"en":"Choose one of your Sylvaneth units inside the zone that is fighting exactly 1 enemy unit. It attacks first (Strike-first) for the rest of the turn.","el":"Διάλεξε μία μονάδα Sylvaneth σου μέσα στη ζώνη που πολεμά με ακριβώς 1 εχθρική μονάδα. Επιτίθεται πρώτη (Strike-first) για το υπόλοιπο της σειράς."},"qpweyh":{"en":"Pick a destroyed Dryads unit or a destroyed non-Hero Revenant Infantry unit. Put a new unit back with half the models (round up). Place it inside the zone and more than 9\" from all enemies.","el":"Διάλεξε μια κατεστραμμένη μονάδα Dryads ή μη-ήρωα Revenant Infantry. Βάλε πίσω νέα μονάδα με τα μισά μοντέλα (στρογγυλοποίηση προς τα πάνω). Τοποθέτησέ την μέσα στη ζώνη και πάνω από 9\" μακριά από όλους τους εχθρούς."},"alzk22":{"en":"If you have fewer than 3 Awakened Wyldwoods, place a new one on the table. It must be more than 3\" from objectives and enemies, more than 12\" from your other Wyldwoods and more than 1\" from other terrain.","el":"Αν έχεις λιγότερα από 3 Awakened Wyldwoods, βάλε ένα νέο στο τραπέζι. Πρέπει να είναι πάνω από 3\" από στόχους και εχθρούς, πάνω από 12\" από τα άλλα Wyldwoods σου και πάνω από 1\" από άλλο έδαφος."},"pjdi17":{"en":"Pick an enemy unit inside the zone. This turn, if the enemy wants to use a command on it and it is not fully within 12\" of one of their Heroes, they must pay 1 extra CP, or the command does nothing (the CP are still lost).","el":"Διάλεξε μια εχθρική μονάδα μέσα στη ζώνη. Αυτή τη σειρά, αν ο αντίπαλος θέλει να χρησιμοποιήσει command πάνω της και δεν είναι ολόκληρη μέσα σε 12\" από Ήρωά του, πρέπει να πληρώσει 1 επιπλέον CP, αλλιώς το command δεν κάνει τίποτα (τα CP χάνονται έτσι κι αλλιώς)."},"10zr74k":{"en":"When you use Endless Growth on a Monster, don't roll: it heals 3.","el":"Όταν χρησιμοποιείς το Endless Growth σε Monster, δεν ρίχνεις ζάρι: γιατρεύεται 3."},"e414oe":{"en":"Pick one of your Sylvaneth units. Until your next turn, +1 to hit while it is fully within 12\" of the enemy general or an enemy Warmaster.","el":"Διάλεξε μία μονάδα Sylvaneth σου. Μέχρι την επόμενη σειρά σου, +1 για να πετύχει (hit) όσο είναι ολόκληρη μέσα σε 12\" από τον εχθρικό general ή έναν εχθρικό Warmaster."},"nuhijz":{"en":"For each Sylvaneth unit or Wyldwood of yours destroyed last turn, pick one Sylvaneth unit: +1 Attacks on its melee weapons for the rest of the turn.","el":"Για κάθε μονάδα Sylvaneth ή Wyldwood σου που καταστράφηκε την προηγούμενη σειρά, διάλεξε μία μονάδα Sylvaneth: +1 Attacks στα όπλα σώμα με σώμα της για το υπόλοιπο της σειράς."},"12az8d3":{"en":"Changes Creeping Dread: the enemy only needs to be fully within 6\" (instead of 12\") of their Hero to avoid the extra cost.","el":"Αλλάζει το Creeping Dread: ο εχθρός αρκεί να είναι ολόκληρος μέσα σε 6\" (αντί για 12\") από Ήρωά του για να αποφύγει το επιπλέον κόστος."},"5hovyo":{"en":"At 10 or more damage, the Antlers weapon has 4 Attacks.","el":"Με 10 ή περισσότερους πόντους ζημιάς, το όπλο Antlers έχει 4 Attacks."},"o6a6ub":{"en":"Spell (7). Pick a visible enemy within 12\" and cast with 2D6. It takes 2D3 mortal damage. If it dies, the nearest terrain without your token gets one. If all terrain already has one, every enemy within 6\" of the target takes D3 mortal damage instead.","el":"Ξόρκι (7). Διάλεξε ορατό εχθρό σε 12\" και ρίξε 2D6 για το ξόρκι. Παίρνει 2D3 θανάσιμη ζημιά. Αν πεθάνει, το κοντινότερο έδαφος χωρίς δείκτη παίρνει δείκτη. Αν όλο το έδαφος έχει ήδη δείκτη, κάθε εχθρός σε 6\" από τον στόχο παίρνει D3 θανάσιμη ζημιά."},"1j6e6qy":{"en":"Heal 2D6 on this unit.","el":"Γιάτρεψε 2D6 σε αυτή τη μονάδα."},"1uwim57":{"en":"If this unit charged this turn: pick a visible enemy within 1\" and roll a dice. On 3+, it takes mortal damage equal to the roll.","el":"Αν αυτή η μονάδα έκανε charge αυτή τη σειρά: διάλεξε ορατό εχθρό σε 1\" και ρίξε ζάρι. Με 3+, παίρνει θανάσιμη ζημιά ίση με το ζάρι."},"1l8xfnx":{"en":"Works even after she is destroyed. Put her back with 8 damage (no ward saves on it), inside the zone and more than 9\" from enemies.","el":"Δουλεύει ακόμη κι αν έχει καταστραφεί. Βάλ' την πίσω με 8 ζημιά (χωρίς ward ζαριές για αυτήν), μέσα στη ζώνη και πάνω από 9\" από εχθρούς."},"e1ulj3":{"en":"Mandatory. Choose 1 effect for this whole round (not the same as last round): Burgeoning = Wyldwoods can pick any terrain your enemy doesn't control. Reaping = +1 to casting and chanting rolls for Sylvaneth within 12\". Dwindling = your Sylvaneth can charge after retreating and take no damage from retreating. Everdusk = Creeping Dread can have up to 3 targets.","el":"Υποχρεωτικό. Διάλεξε 1 εφέ για όλον τον γύρο (όχι το ίδιο με τον προηγούμενο γύρο): Burgeoning = τα Wyldwoods μπορούν να διαλέξουν οποιοδήποτε έδαφος δεν ελέγχει ο εχθρός. Reaping = +1 στα ζάρια ξορκιών και προσευχών για Sylvaneth σε 12\". Dwindling = οι Sylvaneth σου μπορούν να κάνουν charge μετά από υποχώρηση και δεν παίρνουν ζημιά από την υποχώρηση. Everdusk = το Creeping Dread μπορεί να έχει μέχρι 3 στόχους."},"m54cyl":{"en":"If this unit charged this turn, after the fight it can move up to 2D6\". It cannot end in combat.","el":"Αν αυτή η μονάδα έκανε charge αυτή τη σειρά, μετά τη μάχη μπορεί να κινηθεί μέχρι 2D6\". Δεν μπορεί να τελειώσει σε επαφή με εχθρό."},"d4p33":{"en":"If this unit charged: pick your visible Gossamid Archers within 18\" that are not in combat. They can shoot now, but only at enemies fighting this unit.","el":"Αν αυτή η μονάδα έκανε charge: διάλεξε ορατούς Gossamid Archers σου σε 18\" που δεν είναι σε μάχη. Μπορούν να πυροβολήσουν τώρα, αλλά μόνο εχθρούς που πολεμούν αυτή τη μονάδα."},"2jbsyj":{"en":"When the Wyldwood is placed, it gets your green token.","el":"Όταν τοποθετείται το Wyldwood, παίρνει τον πράσινο δείκτη σου."},"o07qq4":{"en":"Every enemy within 3\" of this forest: roll a D3. On 2+, it takes that much mortal damage.","el":"Κάθε εχθρός σε 3\" από αυτό το δάσος: ρίξε D3. Με 2+, παίρνει τόση θανάσιμη ζημιά."},"ou9fq6":{"en":"The nearest terrain without your token gets one (only if the enemy doesn't control it).","el":"Το κοντινότερο έδαφος χωρίς δείκτη σου παίρνει δείκτη (μόνο αν δεν το ελέγχει ο εχθρός)."},"yr2ex6":{"en":"If this unit charged: pick it up and place it again more than 6\" from enemies, inside the zone.","el":"Αν αυτή η μονάδα έκανε charge: σήκωσέ την και βάλ' την ξανά πάνω από 6\" από εχθρούς, μέσα στη ζώνη."},"osyb4q":{"en":"Your Kurnothi units within 12\" get +2\" Move.","el":"Οι μονάδες Kurnothi σου σε 12\" παίρνουν +2\" Move."},"1n66bea":{"en":"Pick an enemy fighting this unit, roll a D3. On 2+, it takes that much mortal damage, then you may move this unit next to it (within 1\").","el":"Διάλεξε εχθρό που πολεμά αυτή τη μονάδα και ρίξε D3. Με 2+, παίρνει τόση θανάσιμη ζημιά και μετά μπορείς να βάλεις αυτή τη μονάδα δίπλα του (σε 1\")."},"19lwdwi":{"en":"At 10 or more damage, the Mandibles weapon has 3 Attacks.","el":"Με 10 ή περισσότερους πόντους ζημιάς, το όπλο Mandibles έχει 3 Attacks."},"1vmoxv7":{"en":"Pick an enemy in the zone, or one you can see in your own territory. Roll a dice. On 3+, +1 to wound against it in combat for the rest of the turn.","el":"Διάλεξε εχθρό μέσα στη ζώνη ή ορατό εχθρό στη δική σου περιοχή. Ρίξε ζάρι. Με 3+, +1 στο wound ενάντια σε αυτόν στη μάχη σώμα με σώμα για το υπόλοιπο της σειράς."},"vtvb2i":{"en":"While fully inside the zone, enemies get -1 to hit and -1 to wound against this unit.","el":"Όσο είναι ολόκληρη μέσα στη ζώνη, οι εχθροί έχουν -1 για να πετύχουν και -1 για να πληγώσουν αυτή τη μονάδα."},"1k5ts5t":{"en":"Enemies within 9\" of this unit cannot Run or Retreat.","el":"Οι εχθροί σε 9\" από αυτή τη μονάδα δεν μπορούν να κάνουν Run ή Retreat."},"12xvqe2":{"en":"Spell (7). Pick up to 3 enemies within 12\" (that she can see) or inside the zone. Cast with 2D6. Each takes D3 mortal damage.","el":"Ξόρκι (7). Διάλεξε μέχρι 3 εχθρούς σε 12\" (που βλέπει) ή μέσα στη ζώνη. Ρίξε 2D6 για το ξόρκι. Καθένας παίρνει D3 θανάσιμη ζημιά."},"1n50p7b":{"en":"If not in combat and did not Run/Retreat: roll 2D6 as a charge roll. Pick the unit up and place it next to an enemy (within 1/2\"), within that many inches of terrain with your token. It counts as having charged.","el":"Αν δεν είναι σε μάχη και δεν έκανε Run/Retreat: ρίξε 2D6 σαν ζαριά charge. Σήκωσε τη μονάδα και βάλ' την δίπλα σε εχθρό (σε 1/2\"), μέσα σε τόσες ίντσες όσο το ζάρι από έδαφος με τον δείκτη σου. Θεωρείται ότι έκανε charge."},"10ad904":{"en":"Models in this unit can be up to 2\" apart (coherency).","el":"Τα μοντέλα αυτής της μονάδας μπορούν να απέχουν μέχρι 2\" μεταξύ τους (coherency)."},"1ldmoa8":{"en":"After shooting, this unit can move up to D6\", but not into combat.","el":"Μετά τους πυροβολισμούς, αυτή η μονάδα μπορεί να κινηθεί μέχρι D6\", αλλά όχι σε επαφή με εχθρό."},"1f6mjzq":{"en":"Pick your non-Hero Revenant units within 12\" that it can see. For the rest of the phase, each time one of their models is killed in combat, roll a dice: on 5+ the attacker takes 1 mortal damage.","el":"Διάλεξε τις μη-ήρωες Revenant μονάδες σου σε 12\" που βλέπει. Για το υπόλοιπο της φάσης, κάθε φορά που ένα μοντέλο τους σκοτώνεται στη μάχη, ρίξε ζάρι: με 5+ ο επιτιθέμενος παίρνει 1 θανάσιμη ζημιά."},"1t4t2":{"en":"Prayer (4). Pick a Sylvaneth unit in the zone or within 12\" and visible. Roll D6 to chant. On 6+ you may pick a second unit. Dryads / non-Hero Revenant Infantry: return up to D3 models. Any other unit: heal 3.","el":"Προσευχή (4). Διάλεξε μονάδα Sylvaneth μέσα στη ζώνη ή σε 12\" και ορατή. Ρίξε D6 για την προσευχή. Με 6+ μπορείς να διαλέξεις και δεύτερη μονάδα. Dryads / μη-ήρωες Revenant Infantry: φέρε πίσω μέχρι D3 μοντέλα. Κάθε άλλη μονάδα: γιάτρεψε 3."},"3ozk0d":{"en":"Pick a single-model enemy that this unit damaged by shooting this phase. Roll a dice. On 3+, -1 Attacks on its weapons until your next turn.","el":"Διάλεξε εχθρό με ένα μόνο μοντέλο που αυτή η μονάδα πλήγωσε με πυροβολισμούς αυτή τη φάση. Ρίξε ζάρι. Με 3+, -1 Attacks στα όπλα του μέχρι την επόμενη σειρά σου."},"14o3chw":{"en":"Pick one of your non-War Machine units within 12\". It can move 3\", even out of combat with the enemies it was fighting. It does not have to end in combat.","el":"Διάλεξε μία μονάδα σου (όχι War Machine) σε 12\". Μπορεί να κινηθεί 3\", ακόμη και να φύγει από τη μάχη με εχθρούς που πολεμούσε. Δεν χρειάζεται να τελειώσει σε μάχη."},"5yrclx":{"en":"While fully inside the zone, attacks against this unit have -1 Rend.","el":"Όσο είναι ολόκληρη μέσα στη ζώνη, οι επιθέσεις εναντίον αυτής της μονάδας έχουν -1 Rend."},"oudwsa":{"en":"If this unit did not move this turn and was not placed this turn, +1 to hit with shooting for the rest of the turn.","el":"Αν αυτή η μονάδα δεν κινήθηκε αυτή τη σειρά και δεν τοποθετήθηκε αυτή τη σειρά, +1 για να πετύχει (hit) στους πυροβολισμούς για το υπόλοιπο της σειράς."},"1pky26p":{"en":"If this unit charged: pick an enemy fighting it. Roll a dice for each of your models fighting it. Each 3+ = 1 mortal damage.","el":"Αν αυτή η μονάδα έκανε charge: διάλεξε εχθρό που τη πολεμά. Ρίξε ένα ζάρι για κάθε μοντέλο σου που πολεμά τον εχθρό. Κάθε 3+ = 1 θανάσιμη ζημιά."},"1j6yiu1":{"en":"Pick an enemy that charged this turn and is fighting this unit. Roll a dice for each of your models fighting it. Each 3+ = 1 mortal damage.","el":"Διάλεξε εχθρό που έκανε charge αυτή τη σειρά και πολεμά αυτή τη μονάδα. Ρίξε ένα ζάρι για κάθε μοντέλο σου που τον πολεμά. Κάθε 3+ = 1 θανάσιμη ζημιά."},"g9k0ls":{"en":"If this unit did not charge, pick an enemy fighting it: -1 Attacks on its melee weapons for the rest of the turn.","el":"Αν αυτή η μονάδα δεν έκανε charge, διάλεξε εχθρό που τη πολεμά: -1 Attacks στα όπλα σώμα με σώμα του για το υπόλοιπο της σειράς."},"1v45ipk":{"en":"Pick an enemy Infantry or Cavalry (not Fly) fighting this unit. Roll a dice. On 3+, it attacks last (Strike-last) for the rest of the turn.","el":"Διάλεξε εχθρό Infantry ή Cavalry (όχι Fly) που πολεμά αυτή τη μονάδα. Ρίξε ζάρι. Με 3+, επιτίθεται τελευταίος (Strike-last) για το υπόλοιπο της σειράς."},"o3hcgg":{"en":"At 10 or more damage, the Guardian Sword has 3 Attacks.","el":"Με 10 ή περισσότερους πόντους ζημιάς, το Guardian Sword έχει 3 Attacks."},"h68aav":{"en":"+2 to the charge roll, but it must finish next to an enemy that is fighting another of your Sylvaneth Heroes.","el":"+2 στη ζαριά charge, αλλά πρέπει να τελειώσει δίπλα σε εχθρό που πολεμά άλλον Ήρωα Sylvaneth σου."},"1mn9udv":{"en":"If fully inside the zone: pick this unit up and place it again within 3\" of a terrain feature, more than 9\" from enemies. Then +1 to its charge rolls this turn.","el":"Αν είναι ολόκληρη μέσα στη ζώνη: σήκωσε τη μονάδα και βάλ' την ξανά σε 3\" από στοιχείο εδάφους, πάνω από 9\" από εχθρούς. Μετά +1 στις ζαριές charge της για αυτή τη σειρά."},"86tyxx":{"en":"If this unit charged: pick it up and place it again more than 9\" from enemies, inside the zone.","el":"Αν αυτή η μονάδα έκανε charge: σήκωσέ την και βάλ' την ξανά πάνω από 9\" από εχθρούς, μέσα στη ζώνη."},"5mvzl1":{"en":"Pick terrain within 18\" without your token. Give it your token.","el":"Διάλεξε έδαφος σε 18\" χωρίς δείκτη σου. Δώσ' του τον δείκτη σου."},"1q7gw72":{"en":"Spell (7). Cast with 2D6 (+1 if she is fully inside the zone). Until your next turn, your Sylvaneth within 12\" have Ward 5+ (a 5 or 6 cancels damage).","el":"Ξόρκι (7). Ρίξε 2D6 για το ξόρκι (+1 αν είναι ολόκληρη μέσα στη ζώνη). Μέχρι την επόμενη σειρά σου, οι Sylvaneth σου σε 12\" έχουν Ward 5+ (με 5 ή 6 αγνοείται η ζημιά)."},"711kf8":{"en":"Pick terrain within 18\" that has your token. The next time she casts a spell (not a Summon) this phase, you can measure range and sight from that terrain instead of from her. The enemy can do the same for Unbind.","el":"Διάλεξε έδαφος σε 18\" με τον δείκτη σου. Την επόμενη φορά που ρίχνει ξόρκι (όχι Summon) αυτή τη φάση, μπορείς να μετρήσεις απόσταση και ορατότητα από εκείνο το έδαφος αντί από αυτήν. Ο εχθρός μπορεί να κάνει το ίδιο για το Unbind."},"1ti8nj2":{"en":"Pick an enemy fighting this unit. It becomes Infested for the rest of the battle. Infested enemies move at most 6\" (except when charging).","el":"Διάλεξε εχθρό που πολεμά αυτή τη μονάδα. Γίνεται Infested για το υπόλοιπο της μάχης. Οι Infested εχθροί κινούνται το πολύ 6\" (εκτός από charge)."},"1t51lfg":{"en":"If this unit charged this turn, its melee weapons have Crit (2 Hits): a critical hit counts as 2 hits.","el":"Αν αυτή η μονάδα έκανε charge αυτή τη σειρά, τα όπλα σώμα με σώμα έχουν Crit (2 Hits): ένα κρίσιμο χτύπημα μετράει για 2."},"1qnf61q":{"en":"While in combat and not charged this turn, +1 Damage on this unit's melee weapons.","el":"Όσο είναι σε μάχη και δεν έκανε charge αυτή τη σειρά, +1 Damage στα όπλα σώμα με σώμα της μονάδας."},"hq1kr0":{"en":"Pick a visible enemy within 10\". Roll a dice. If it is higher than the enemy's Health, 1 of its models dies.","el":"Διάλεξε ορατό εχθρό σε 10\". Ρίξε ζάρι. Αν είναι μεγαλύτερο από το Health του εχθρού, 1 μοντέλο του σκοτώνεται."},"12i0clb":{"en":"At 10 or more damage, Sweeping Blows has 3 Attacks.","el":"Με 10 ή περισσότερους πόντους ζημιάς, το Sweeping Blows έχει 3 Attacks."},"1rr37r1":{"en":"Pick an enemy damaged by this unit's Strangleroots this turn. Roll a dice (+1 if it is inside the zone). On 3+, -1 to hit for its attacks until your next turn.","el":"Διάλεξε εχθρό που πληγώθηκε από τα Strangleroots αυτής της μονάδας αυτή τη σειρά. Ρίξε ζάρι (+1 αν είναι μέσα στη ζώνη). Με 3+, -1 για να πετύχει στις επιθέσεις του μέχρι την επόμενη σειρά σου."},"1lunlgi":{"en":"Pick your Forest Elders within this unit's combat range. Roll a dice for each. On 3+, +1 to hit in combat until your next turn.","el":"Διάλεξε τους Forest Elders σου που είναι στην εμβέλεια μάχης αυτής της μονάδας. Ρίξε ζάρι για καθέναν. Με 3+, +1 για να πετύχουν στη μάχη μέχρι την επόμενη σειρά σου."},"9x5rqq":{"en":"Pick visible terrain within 12\" with your token, and a destroyed non-Unique Kurnothi or Treelord unit. Place 1 model of it back within 6\" of that terrain, more than 9\" from enemies. Remove the token from the terrain. If it was a Treelord, it comes back with 10 damage (no ward saves on it).","el":"Διάλεξε ορατό έδαφος σε 12\" με τον δείκτη σου και μια κατεστραμμένη μονάδα Kurnothi ή Treelord (όχι Unique). Βάλε 1 μοντέλο της πίσω σε 6\" από εκείνο το έδαφος, πάνω από 9\" από εχθρούς. Αφαίρεσε τον δείκτη από το έδαφος. Αν ήταν Treelord, επιστρέφει με 10 ζημιά (χωρίς ward ζαριές για αυτήν)."},"v320h4":{"en":"Re-roll that chanting roll.","el":"Ξαναρίξε αυτή τη ζαριά προσευχής."},"jf14t3":{"en":"Your Sylvaneth within 12\" have Ward 6+. Enemies within 12\" get -1 to their ward rolls.","el":"Οι Sylvaneth σου σε 12\" έχουν Ward 6+. Οι εχθροί σε 12\" έχουν -1 στις ward ζαριές τους."},"15i2wvu":{"en":"If not in combat: pick it up and place it again more than 9\" from enemies (except Wizards/Priests: more than 3\" from them).","el":"Αν δεν είναι σε μάχη: σήκωσέ το και βάλ' το ξανά πάνω από 9\" από εχθρούς (εκτός Wizards/Priests: πάνω από 3\" από αυτούς)."},"1u81byd":{"en":"Enemies fighting this Manifestation get -1 to casting, unbinding, chanting and banishing rolls.","el":"Οι εχθροί που πολεμούν αυτό το Manifestation έχουν -1 στις ζαριές ξορκιών, unbinding, προσευχών και banishing."},"15z803j":{"en":"Enemies within 6\" of this Manifestation get -1 to hit.","el":"Οι εχθροί σε 6\" από αυτό το Manifestation έχουν -1 για να πετύχουν."},"3673ia":{"en":"If not placed this turn: +10 Attacks on its ranged weapons this phase, but it can only shoot enemies within 9\".","el":"Αν δεν τοποθετήθηκε αυτή τη σειρά: +10 Attacks στα όπλα εξ αποστάσεως αυτή τη φάση, αλλά μπορεί να πυροβολήσει μόνο εχθρούς σε 9\"."},"dkefb3":{"en":"Spell (6). A Sylvaneth Wizard casts on a visible Sylvaneth unit within 12\". +1 to wound in combat for the rest of the turn.","el":"Ξόρκι (6). Ένας Sylvaneth Wizard το ρίχνει σε ορατή μονάδα Sylvaneth σε 12\". +1 στο wound στη μάχη για το υπόλοιπο της σειράς."},"phw03":{"en":"Spell (6). A Sylvaneth Wizard casts on a visible Sylvaneth unit within 12\". This turn it can charge even if it ran.","el":"Ξόρκι (6). Ένας Sylvaneth Wizard το ρίχνει σε ορατή μονάδα Sylvaneth σε 12\". Αυτή τη σειρά μπορεί να κάνει charge ακόμη κι αν έκανε Run."},"70qbky":{"en":"Spell (5). Pick a visible enemy within 18\". Until your next turn it cannot Run and gets -1 to charge rolls.","el":"Ξόρκι (5). Διάλεξε ορατό εχθρό σε 18\". Μέχρι την επόμενη σειρά σου δεν μπορεί να κάνει Run και έχει -1 στις ζαριές charge."},"7519hg":{"en":"The first time this unit would be destroyed: roll a dice. On 3+ it survives, ignores the remaining damage, and heals D3.","el":"Την πρώτη φορά που αυτή η μονάδα θα καταστραφεί: ρίξε ζάρι. Με 3+ επιβιώνει, αγνοεί την υπόλοιπη ζημιά και γιατρεύεται D3."},"26cqlz":{"en":"Pick a visible enemy within 6\". This turn your Sylvaneth Companion weapons get +1 Damage against it.","el":"Διάλεξε ορατό εχθρό σε 6\". Αυτή τη σειρά τα όπλα Companion των Sylvaneth σου έχουν +1 Damage εναντίον του."},"6k9ve6":{"en":"Pick an enemy this unit damaged in combat this turn. It gets -1 to save for the rest of the battle. Works even if this unit is destroyed.","el":"Διάλεξε εχθρό που αυτή η μονάδα πλήγωσε στη μάχη αυτή τη σειρά. Έχει -1 στο save για το υπόλοιπο της μάχης. Δουλεύει ακόμη κι αν αυτή η μονάδα καταστραφεί."},"gdl5nl":{"en":"+1 to this unit's casting rolls. If it is not a Wizard, it can Unbind as if Wizard(1).","el":"+1 στις ζαριές ξορκιών αυτής της μονάδας. Αν δεν είναι Wizard, μπορεί να κάνει Unbind σαν να ήταν Wizard(1)."},"1f2n02v":{"en":"Pick a visible enemy Hero. Its Move is halved for the rest of the turn.","el":"Διάλεξε ορατό εχθρικό Ήρωα. Το Move του μισεύει για το υπόλοιπο της σειράς."},"goj93":{"en":"Only if this unit is fully inside the zone. Pick this unit and 1 other Sylvaneth unit within its combat range. Pick both up and place them again inside the zone, more than 9\" from enemies.","el":"Μόνο αν αυτή η μονάδα είναι ολόκληρη μέσα στη ζώνη. Διάλεξε αυτή τη μονάδα και 1 άλλη μονάδα Sylvaneth στην εμβέλεια μάχης της. Σήκωσε και τις δύο και βάλ' τες ξανά μέσα στη ζώνη, πάνω από 9\" από εχθρούς."},"11ow2f7":{"en":"Prayer (4). A Sylvaneth Priest chants for a Sylvaneth unit in the zone or visible within 12\". Until your next turn enemies get -1 to wound it. If the roll was 8+ also choose: heal 3, OR ignore all save modifiers on it (not for Monsters).","el":"Προσευχή (4). Ένας Sylvaneth Priest προσεύχεται για μονάδα Sylvaneth μέσα στη ζώνη ή ορατή σε 12\". Μέχρι την επόμενη σειρά σου οι εχθροί έχουν -1 για να την πληγώσουν. Αν το ζάρι ήταν 8+, διάλεξε επιπλέον: γιάτρεψε 3 Ή αγνόησε όλους τους τροποποιητές save (όχι για Monsters)."},"37k0ip":{"en":"Prayer (4). A Sylvaneth Priest picks an enemy in the zone or visible within 18\". On 8+ a second enemy too. Until your next turn, each time they move and end inside the zone, they take D3 mortal damage.","el":"Προσευχή (4). Ένας Sylvaneth Priest διαλέγει εχθρό μέσα στη ζώνη ή ορατό σε 18\". Με 8+ και δεύτερο εχθρό. Μέχρι την επόμενη σειρά σου, κάθε φορά που κινούνται και τελειώνουν μέσα στη ζώνη, παίρνουν D3 θανάσιμη ζημιά."},"1shtath":{"en":"Prayer (5). A Sylvaneth Priest picks a Sylvaneth unit in the zone or visible within 12\". On 10+ a second unit too. Until your next turn, +1 Rend on their melee weapons.","el":"Προσευχή (5). Ένας Sylvaneth Priest διαλέγει μονάδα Sylvaneth μέσα στη ζώνη ή ορατή σε 12\". Με 10+ και δεύτερη μονάδα. Μέχρι την επόμενη σειρά σου, +1 Rend στα όπλα σώμα με σώμα τους."}};
